    const HISTORIES: &'static [::sce_rust_runtime::saved_state::HistoryDecl<
        ::sce_rust_runtime::NoHistory,
    >] = &[];

    fn save_at(
        &self,
        wall_now_ms: u64,
    ) -> Result<
        ::sce_rust_runtime::saved_state::SavedState,
        ::sce_rust_runtime::saved_state::StateRefusal,
    > {
        let policy = self.policy();
        ::sce_rust_runtime::saved_state::save(
            self,
            &Self::SHAPE,
            vec![
                (
                    "items".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.items),
                ),
                (
                    "draft".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.draft),
                ),
                (
                    "last".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.last),
                ),
                (
                    "openCount".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.open_count),
                ),
                (
                    "startedCount".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.started_count),
                ),
                (
                    "doneCount".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.done_count),
                ),
                (
                    "checks".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.checks),
                ),
                (
                    "refusals".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.refusals),
                ),
            ],
            ::sce_rust_runtime::saved_state::save_history(self.policy(), Self::HISTORIES),
            Vec::new(),
            wall_now_ms,
        )
    }

    fn judge(
        saved: &::sce_rust_runtime::saved_state::SavedState,
    ) -> Result<(), ::sce_rust_runtime::saved_state::StateRefusal> {
        // What a restore reads, read and let go: the shape and the revisions,
        // the history, every variable, and then the configuration, the queues,
        // the invocations and each running child by its own document.
        let saved = &::sce_rust_runtime::saved_state::upgrade(saved, &Self::SHAPE)?;
        ::sce_rust_runtime::saved_state::restore_history::<StaticStateAlgorithmEnumPolicy>(
            saved,
            Self::HISTORIES,
        )?;
        let _: Vec<StaticStateAlgorithmEnumItemRecord> =
            ::sce_rust_runtime::saved_state::bounded(saved.variable("items")?, "items", 4)?;
        let _: StaticStateAlgorithmEnumItemRecord =
            ::sce_rust_runtime::saved_state::SavedValue::from_saved(
                saved.variable("draft")?,
                "draft",
            )?;
        let _: StaticStateAlgorithmEnumStatusEnum =
            ::sce_rust_runtime::saved_state::SavedValue::from_saved(
                saved.variable("last")?,
                "last",
            )?;
        let _: u32 = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("openCount")?,
            "openCount",
        )?;
        let _: u32 = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("startedCount")?,
            "startedCount",
        )?;
        let _: u32 = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("doneCount")?,
            "doneCount",
        )?;
        let _: u32 = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("checks")?,
            "checks",
        )?;
        let _: u32 = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("refusals")?,
            "refusals",
        )?;
        ::sce_rust_runtime::saved_state::judge::<StaticStateAlgorithmEnumPolicy>(saved)
    }

    fn restore_with(
        mut policy: StaticStateAlgorithmEnumPolicy,
        saved: &::sce_rust_runtime::saved_state::SavedState,
        clock: ::sce_rust_runtime::SceClock,
        wall_now_ms: u64,
    ) -> Result<Self, ::sce_rust_runtime::saved_state::StateRefusal> {
        // The shape, the revision of each record schema, and each record of an
        // earlier revision grown by the defaults of the fields added since, so
        // what is read below is a state of this machine.
        let saved = &::sce_rust_runtime::saved_state::upgrade(saved, &Self::SHAPE)?;
        // Judged with the configuration and before any value is written, so a
        // refused restore holds no half of a state. A document with no
        // `<history>` refuses any a saved state records.
        ::sce_rust_runtime::saved_state::restore_history::<StaticStateAlgorithmEnumPolicy>(
            saved,
            Self::HISTORIES,
        )?;
        policy.items =
            ::sce_rust_runtime::saved_state::bounded(saved.variable("items")?, "items", 4)?;
        policy.draft = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("draft")?,
            "draft",
        )?;
        policy.last = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("last")?,
            "last",
        )?;
        policy.open_count = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("openCount")?,
            "openCount",
        )?;
        policy.started_count = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("startedCount")?,
            "startedCount",
        )?;
        policy.done_count = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("doneCount")?,
            "doneCount",
        )?;
        policy.checks = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("checks")?,
            "checks",
        )?;
        policy.refusals = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("refusals")?,
            "refusals",
        )?;
        ::sce_rust_runtime::saved_state::enter(policy, saved, clock, wall_now_ms)
    }
