    // keeps the ordered set. `Event::Null` asks for eventless transitions.
    #[doc = "SCE-MAP: static_state_algorithm_enum.scxml:22 :: _machine"]
    // SCE-MAP: static_state_algorithm_enum.scxml:22 :: _machine
